/**
 * Injects the UBL elements required for ZATCA credit/debit notes (BR-KSA-17,
 * BR-KSA-56) into XML generated by @talha7k/zatca's generateInvoiceXml().
 *
 * Why not generateCreditNoteXml()? That builder omits empty
 * AccountingCustomerParty for Simplified (B2C) notes. ZATCA's UBL schema still
 * requires the element, so reporting fails with XSD_ZATCA_INVALID / "Invoice
 * Format Issue". Invoice XML always emits the empty customer party; we then
 * patch in Note, BillingReference, and PaymentMeans/InstructionNote.
 *
 * Element ordering matches the package's internal buildCreditNoteXml() in
 * dist/xml/credit-note.js — not inferred from partial XSD errors.
 *
 * @param {string} xml The XML from generateInvoiceXml()
 * @param {{
 *   reason: string
 *   originalInvoiceNumber: string
 *   originalInvoiceUuid: string
 *   originalInvoiceDate: string
 * }} note
 */
export function patchCreditDebitNoteXml(xml, note) {
  let patched = xml

  const reason = escapeXmlText(note.reason)
  const originalInvoiceNumber = escapeXmlText(note.originalInvoiceNumber)
  const originalInvoiceUuid = escapeXmlText(note.originalInvoiceUuid)
  const originalInvoiceDate = escapeXmlText(note.originalInvoiceDate)

  // Note immediately after InvoiceTypeCode, BEFORE DocumentCurrencyCode.
  const noteBlock = `  <cbc:Note>${reason}</cbc:Note>\n`
  if (patched.includes('<cbc:InvoiceTypeCode')) {
    patched = patched.replace(
      /(<cbc:InvoiceTypeCode[^>]*>.*?<\/cbc:InvoiceTypeCode>\n)/,
      `$1${noteBlock}`,
    )
  } else {
    throw new Error(
      'Could not find <cbc:InvoiceTypeCode> to insert <cbc:Note> after',
    )
  }

  // BillingReference after TaxCurrencyCode, before AdditionalDocumentReference.
  const billingReferenceBlock = `  <cac:BillingReference>
    <cac:InvoiceDocumentReference>
      <cbc:ID>${originalInvoiceNumber}</cbc:ID>
      <cbc:UUID>${originalInvoiceUuid}</cbc:UUID>
      <cbc:IssueDate>${originalInvoiceDate}</cbc:IssueDate>
    </cac:InvoiceDocumentReference>
  </cac:BillingReference>\n`

  if (patched.includes('<cbc:TaxCurrencyCode>')) {
    patched = patched.replace(
      /(<cbc:TaxCurrencyCode>.*?<\/cbc:TaxCurrencyCode>\n)/,
      `$1${billingReferenceBlock}`,
    )
  } else if (patched.includes('<cbc:DocumentCurrencyCode>')) {
    patched = patched.replace(
      /(<cbc:DocumentCurrencyCode>.*?<\/cbc:DocumentCurrencyCode>\n)/,
      `$1${billingReferenceBlock}`,
    )
  } else {
    throw new Error(
      'Could not find currency code element to insert <cac:BillingReference> after',
    )
  }

  const paymentMeansBlock = `  <cac:PaymentMeans>
    <cbc:PaymentMeansCode>10</cbc:PaymentMeansCode>
    <cbc:InstructionNote>${reason}</cbc:InstructionNote>
  </cac:PaymentMeans>\n`

  if (patched.includes('</cac:AccountingCustomerParty>')) {
    patched = patched.replace(
      '</cac:AccountingCustomerParty>',
      `</cac:AccountingCustomerParty>\n\n${paymentMeansBlock}`,
    )
  } else if (patched.includes('</cac:AccountingSupplierParty>')) {
    patched = patched.replace(
      '</cac:AccountingSupplierParty>',
      `</cac:AccountingSupplierParty>\n\n${paymentMeansBlock}`,
    )
  } else {
    throw new Error(
      'Could not find an anchor point to insert <cac:PaymentMeans>',
    )
  }

  return patched
}

/**
 * @param {unknown} value
 */
function escapeXmlText(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;')
}
